fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let maxsplit = maxsplit as usize; // Convert to usize for easier indexing
    let mut result = Vec::with_capacity(a.len()); // Preallocate space for the result

    for s in a {
        if maxsplit == 0 {
            // If maxsplit is 0, return the original string in a single-element vector
            result.push(vec![s]);
        } else {
            // Perform the right split
            let mut parts: Vec<String> = s.rsplit(&sep).map(String::from).collect();
            // Reverse the parts to maintain the original order
            parts.reverse();
            // If the number of parts exceeds maxsplit + 1, truncate it
            if parts.len() > maxsplit + 1 {
                let split_index = parts.len() - maxsplit - 1;
                let last_part = parts.split_off(split_index);
                // Push the last part as a single string
                parts.push(last_part.join(&sep));
            }
            result.push(parts);
        }
    }

    result
}